CREATE OR REPLACE FUNCTION public.create_pending_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n text:=btrim(coalesce(NEW.raw_user_meta_data->>'name','')); BEGIN IF length(n)<2 OR length(n)>120 THEN RAISE EXCEPTION 'Informe um nome entre 2 e 120 caracteres.'; END IF; INSERT INTO public.profiles(id,name,email) VALUES(NEW.id,n,coalesce(NEW.email,'')); RETURN NEW; END $$;